import Vue from 'vue'
import Router from 'vue-router'
import Home from '@/components/Home'
import DocsView from '@/components/DocsView'

Vue.use(Router)

export default new Router({
  mode: 'history',
  base: '/tech-log/',
  routes: [
    {
      path: '/',
      name: 'Home',
      component: Home
    },
    {
      // 文档路由：doc 就是 src/assets/docs 里的文件名（去掉 .md 后缀）
      // 新增 markdown 文件后会自动生效，无需在这里注册
      path: '/docs/:doc',
      name: 'DocsView',
      component: DocsView
    },
    {
      // 兼容旧链接 /git/xxx（新链接统一走 /docs/xxx）
      path: '/git/:doc',
      component: DocsView
    }
  ],
  // 切换文档时回到页面顶部（浏览器前进/后退时恢复原来的位置）
  scrollBehavior (to, from, savedPosition) {
    if (savedPosition) {
      return savedPosition
    }
    // 带 #锚点（比如搜索结果）：滚到对应小节，留出固定导航栏的高度
    if (to.hash) {
      return { selector: to.hash, offset: { x: 0, y: 84 } }
    }
    return { x: 0, y: 0 }
  }
})



